UPDATE university_scholarships SET scholarship_name = 'Danish State Scholarships at Aarhus University', availability_status = 'available', funding_type = 'Tuition Waiver', max_scholarship = 'Tuition waiver (full or partial; 100% at Natural/Technical Sciences), at Arts and Aarhus BSS combined with a monthly living grant; typically only 1-2 per programme', covers_tuition = true, covers_living_expenses = true, valued_aspect = 'Excellent academic qualifications (assessed automatically with the admission application)', eligibility_notes = 'For non-EU/EEA/Swiss master''s applicants liable for tuition fees (EU/EEA/Swiss cannot apply). No separate application: apply for the master''s by 15 January (summer) or 15 September (winter) and you are assessed automatically - do not upload extra scholarship documents. Arts/Aarhus BSS = waiver + monthly living grant; Natural/Technical Sciences = waiver only (award process until 1 April/1 November - do not decline admission before then if you depend on it). The award is tied to the specific programme and cannot be transferred; offer carries a very short acceptance deadline.', official_url = 'https://masters.au.dk/scholarships-and-grants', source_url = 'https://masters.au.dk/scholarships-and-grants', verification_status = 'verified', last_verified_at = now() WHERE id = 183;
